    const invoices = [
      {
        number: 'INV-003',
        customerId: 'C-001',
        issueDate: '2026-10-03',
        dueDate: '2026-10-31',
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
        payments: [],
      },
      {
        number: 'INV-001',
        customerId: 'C-001',
        issueDate: '2026-10-01',
        dueDate: '2026-10-31',
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
